      "path": "src/host/detail.ts",
      "content": "/** The on-demand detail route of the split `contextTimeline` generation: one targeted read per viewing client serves\n * the heavy collections the slim head omits — a live session's state off the registry's `stateOf` (no second fold), a\n * cold one's immutable log folded from init, anything else a typed `null`. */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { FoldBounds } from './config'\nimport { type ColdReadGate, makeColdReadGate } from './coldRead'\nimport { type ConnectionHostFace, registerPostRoute } from './connection'\nimport { applyTimeline } from './fold'\nimport { createTimelineState } from './foldState'\nimport { buildTimelineDetail, buildTimelineHead } from './foldWire'\nimport type { ContextTimelineDetail, Snapshot } from '../shared/types'\nimport type { TimelineState } from './foldState'\n\nexport const DETAIL_ROUTE = '/api/dsh-context/detail'\n\n/** ~13ms synchronous fold per chunk, so a cold 30k-event fold yields instead of blocking the request. */\nconst FOLD_YIELD_EVENTS = 1_000\n\n/** Cold payload cache: one payload is bounded by the fold bounds (≲1MB), and the durable revision in the key makes a stale serve\n * structurally impossible, so a page reload re-serves instead of refolding the whole log. */\nconst PAYLOAD_CACHE_MAX = 4\n\n/** One cached cold payload: the same `(identity, id, revision)` trust tuple dsh's own observation reader keys its cache on, so a swapped\n * backend can never alias a stale serve. */\ninterface ColdPayload {\n  persistence: unknown\n  revision: string\n  value: ContextTimelineDetail\n}\n\n/** The durable change token; absent on a live observation, a moving target that must never key the cache. */\nfunction revisionOf(observation: unknown): string | undefined {\n  const revision = (observation as { revision?: unknown } | null)?.revision\n  return typeof revision === 'string' && revision !== '' ? revision : undefined\n}\n\n/** The head-only wire value of a built detail. An absent head rides as `undefined`: the JSON reply drops it, and the\n * client's re-proof answers the typed malformed failure. */\nfunction headOfDetail(detail: { rev: number; head?: unknown }): { rev: number; head?: unknown } {\n  return { rev: detail.rev, head: detail.head }\n}\n\nfunction headPayloadOf(state: TimelineState): { rev: number; head: Snapshot } {\n  return { rev: state.detailRev ?? 0, head: buildTimelineHead(state) }\n}\n\nexport interface DetailChannelGate {\n  readonly live: boolean\n}\n\ninterface SessionsHostFace {\n  get?(id: string): unknown\n}\n\ninterface SessionQueryFace {\n  observeSession?(id: string, options: unknown): Promise<unknown>\n}\n\nfunction reply(value: unknown): Response {\n  return Response.json(value, { headers: { 'cache-control': 'no-store' } })\n}\n\nfunction failure(code: string, message: string): Response {\n  return reply({ ok: false, error: { code, message } })\n}\n\n/** Either service unloading withdraws the route and closes the gate. */\nexport function watchDetailChannel(ctx: Context, bounds: FoldBounds, coldReads: ColdReadGate = makeColdReadGate()): DetailChannelGate {\n  const gate = { live: false }\n  // The cold payload cache lives in this closure: a config remount re-runs the watch, so a bounds change never serves a payload folded\n  // under different bounds.\n  const payloads = new Map<string, ColdPayload>()\n  ctx.inject(['connection', 'sessions'], (c) => {\n    const sessions = c.get('sessions') as SessionsHostFace | undefined\n    const getSession = typeof sessions?.get === 'function' ? sessions.get.bind(sessions) : undefined\n    if (getSession === undefined) return\n    const projections = ctx.sessionProjections\n\n    const handler = async (request: Request): Promise<Response> => {\n      let sessionId: unknown\n      let headOnly = false\n      try {\n        const body: unknown = await request.json()\n        sessionId = body !== null && typeof body === 'object'\n          ? (body as { sessionId?: unknown }).sessionId\n          : undefined\n        headOnly = body !== null && typeof body === 'object' && (body as { head?: unknown }).head === true\n      } catch {\n        return failure('dsh-context/bad-request', 'body is not JSON')\n      }\n      if (typeof sessionId !== 'string' || sessionId === '') {\n        return failure('dsh-context/bad-request', 'missing sessionId')\n      }\n      try {\n        const session = getSession(sessionId)\n        if (session !== undefined && session !== null) {\n          // Live session: the registry's current fold state — no second fold, and it is never mutated.\n          const state = projections.stateOf(session as never, 'contextTimeline')\n          if (state === undefined) return reply({ ok: true, value: null })\n          // A head read (the agent cards) serves the envelope scalars only: the collections are ~200× the bytes and\n          // the reader discards them.\n          return reply({ ok: true, value: headOnly ? headPayloadOf(state) : buildTimelineDetail(state, bounds) })\n        }\n        // Cold session: observe it and fold from its immutable log through the shared cold-read gate; a skip under heap\n        // pressure resolves to the same typed null, and an unchanged durable revision re-serves the cached payload.\n        const query = ctx.get('sessionQuery') as SessionQueryFace | undefined\n        const observe = typeof query?.observeSession === 'function'\n          ? query.observeSession.bind(query)\n          : undefined\n        if (observe === undefined) return reply({ ok: true, value: null })\n        const value = await coldReads.admit(async () => {\n          const observation = await observe(sessionId, { projectionMode: 'none' })\n          try {\n            const persistence: unknown = ctx.get('sessionPersistence')\n            const revision = revisionOf(observation)\n            if (revision !== undefined) {\n              const hit = payloads.get(sessionId)\n              if (hit !== undefined && hit.revision === revision && hit.persistence === persistence) {\n                payloads.delete(sessionId)\n                payloads.set(sessionId, hit)\n                return headOnly ? headOfDetail(hit.value) : hit.value\n              }\n            }\n            const events = (observation as { events?: unknown } | null)?.events\n            if (!Array.isArray(events)) return null\n            let state = createTimelineState()\n            let folded = 0\n            for (const ev of events) {\n              state = applyTimeline(state, ev as never, bounds)\n              if (++folded % FOLD_YIELD_EVENTS === 0) await new Promise(resolve => setTimeout(resolve, 0))\n            }\n            // The full detail is built (and cached) whenever the durable revision can key it, so a later full read\n            // re-serves; only an unkeyable read skips the collections build when just the head was asked.\n            if (revision !== undefined) {\n              const detail = buildTimelineDetail(state, bounds)\n              payloads.delete(sessionId)\n              payloads.set(sessionId, { persistence, revision, value: detail })\n              for (const oldest of payloads.keys()) {\n                if (payloads.size <= PAYLOAD_CACHE_MAX) break\n                payloads.delete(oldest)\n              }\n              return headOnly ? headOfDetail(detail) : detail\n            }\n            if (headOnly) return headPayloadOf(state)\n            return buildTimelineDetail(state, bounds)\n          } finally {\n            const dispose = (observation as { [Symbol.dispose]?: unknown } | null)?.[Symbol.dispose]\n            if (typeof dispose === 'function') dispose.call(observation)\n          }\n        })\n        return reply({ ok: true, value: value ?? null })\n      } catch (err) {\n        return failure('gateway/internal', err instanceof Error ? err.message : String(err))\n      }\n    }\n\n    // A hostile or rejecting registry leaves the route absent: the gate stays closed.\n    if (!registerPostRoute(c, c.get('connection') as ConnectionHostFace | undefined, DETAIL_ROUTE, handler, 'dsh-context: detail route')) return\n    gate.live = true\n    return () => {\n      gate.live = false\n    }\n  })\n  return gate\n}\n"
    },
    {
      "path": "src/host/coldRead.ts",
      "content": "/** The host-wide cold-read governor: every cold read materializes a whole durable log, so the gate admits one at a time (FIFO) and only\n * below the heap ceiling; a skipped read takes the caller's designed no-data path, never a visible failure. */\n\nimport { getHeapStatistics } from 'node:v8'\n\nexport interface HeapReading {\n  used: number\n  limit: number\n}\n\nexport interface ColdReadGate {\n  /** Resolves `undefined` when the read was skipped under pressure — the caller's no-data path answers instead. */\n  admit<T>(read: () => Promise<T>): Promise<T | undefined>\n}\n\n/** Two-thirds of the process's own V8 ceiling; the top third is headroom for the read and the harness's own logs. */\nconst HIGH_WATER = 2 / 3\n\nfunction v8Reading(): HeapReading {\n  const stats = getHeapStatistics()\n  return { used: stats.used_heap_size, limit: stats.heap_size_limit }\n}\n\nconst noop = (): void => {}\n\n/** One governor per host process. `reading` is injectable for tests; a throwing or garbage probe fails OPEN, since the meter must never\n * block a read. */\nexport function makeColdReadGate(reading: () => HeapReading = v8Reading): ColdReadGate {\n  const clear = (): boolean => {\n    try {\n      const { used, limit } = reading()\n      if (!Number.isFinite(used) || !Number.isFinite(limit) || limit <= 0) return true\n      return used < limit * HIGH_WATER\n    } catch {\n      return true\n    }\n  }\n  let tail: Promise<unknown> = Promise.resolve()\n  return {\n    admit<T>(read: () => Promise<T>): Promise<T | undefined> {\n      // The headroom check runs at the front of the queue, not at queue time — pressure changes while waiting.\n      const run = tail.then(() => (clear() ? read() : undefined))\n      tail = run.then(noop, noop)\n      return run\n    },\n  }\n}\n"
    },
    {
      "path": "src/host/pricing.ts",
      "content": "/** Token pricing: the harness token-meter's fixed-density heuristic (`dsh-token-meter/estimate.ts`) — 4 chars ≈ 1\n * token, +4 per content block, +4 role framing. One divergence: `image` blocks price by pixel dimensions through the\n * vision docs calculator (shared/imageTokens.ts), falling back to the meter's JSON price. */\n\nimport { estimateTextTokens } from '../shared/estimate'\nimport { estimateImageTokens } from '../shared/imageTokens'\n\nconst CHARS_PER_TOKEN = 4\nconst BLOCK_OVERHEAD = 4\nconst ROLE_OVERHEAD = 4\n\nexport function estimateToolsTotal(tools: unknown[]): number {\n  return tools.length > 0\n    ? Math.ceil(JSON.stringify(tools).length / CHARS_PER_TOKEN) + BLOCK_OVERHEAD\n    : 0\n}\n\nexport interface ContentBlock {\n  type: string\n  text?: string\n  name?: string\n  arguments?: string\n  content?: ContentBlock[]\n  callId?: string\n  /** Durable image attachment ref; the log is untrusted, so the fold re-proves its shape. */\n  attachment?: { width?: unknown; height?: unknown } | null\n}\n\nfunction estimateBlocks(blocks: unknown): number {\n  let tokens = 0\n  if (!Array.isArray(blocks)) return 0\n  for (const item of blocks) {\n    // A null or primitive element prices as bare overhead instead of throwing the whole fold.\n    if (item === null || typeof item !== 'object') {\n      tokens += BLOCK_OVERHEAD\n      continue\n    }\n    const block = item as ContentBlock\n    switch (block.type) {\n      case 'text':\n      case 'reasoning':\n        tokens += estimateTextTokens(block.text || '')\n        break\n      case 'tool-call':\n        tokens += Math.ceil((block.name || '').length / CHARS_PER_TOKEN)\n          + Math.ceil((block.arguments || '').length / CHARS_PER_TOKEN) + BLOCK_OVERHEAD\n        break\n      case 'image': {\n        const ref = block.attachment\n        const priced = ref !== null && typeof ref === 'object'\n          && typeof ref.width === 'number' && typeof ref.height === 'number'\n          ? estimateImageTokens(ref.width, ref.height)\n          : null\n        tokens += (priced ?? Math.ceil(JSON.stringify(block).length / CHARS_PER_TOKEN)) + BLOCK_OVERHEAD\n        break\n      }\n      default:\n        tokens += BLOCK_OVERHEAD + Math.ceil(JSON.stringify(block).length / CHARS_PER_TOKEN)\n    }\n  }\n  return tokens\n}\n\n/** Price one surface message exactly like dsh's meter: an empty-content assistant/developer event projects to NO message, so it prices 0.\n */\nexport function estimateMessage(message: { content?: ContentBlock[] } | undefined | null, emptyIsZero = false): number {\n  if (emptyIsZero && (message === null || message === undefined\n    || !Array.isArray(message.content) || message.content.length === 0)) {\n    return 0\n  }\n  return estimateBlocks(message?.content) + ROLE_OVERHEAD\n}\n\n/** Per-tool price; the total uses the meter's whole-array price. */\nexport function estimateToolSchema(tool: unknown): number {\n  return Math.ceil(JSON.stringify(tool).length / CHARS_PER_TOKEN) + BLOCK_OVERHEAD\n}\n\n/** Count image blocks recursively; seeds each node's `imgs`, summed over the LIVE surface only. */\nexport function imageCountOf(blocks: unknown): number {\n  let count = 0\n  if (!Array.isArray(blocks)) return 0\n  for (const item of blocks) {\n    if (item === null || typeof item !== 'object') continue\n    const block = item as ContentBlock\n    if (block.type === 'image') count++\n    else if (Array.isArray(block.content)) count += imageCountOf(block.content)\n  }\n  return count\n}\n\nexport function firstText(blocks: unknown): string {\n  if (!Array.isArray(blocks)) return ''\n  for (const item of blocks) {\n    if (item === null || typeof item !== 'object') continue\n    const b = item as ContentBlock\n    if (b.type === 'text' && typeof b.text === 'string' && b.text.trim() !== '') {\n      return b.text.replace(/\\s+/g, ' ').trim().slice(0, 80)\n    }\n  }\n  return ''\n}\n\nexport function toolCallNames(blocks: unknown): string[] {\n  const names: string[] = []\n  if (!Array.isArray(blocks)) return names\n  for (const item of blocks) {\n    if (item === null || typeof item !== 'object') continue\n    const b = item as ContentBlock\n    if (b.type === 'tool-call' && typeof b.name === 'string') names.push(b.name)\n  }\n  return names\n}\n\nexport interface MessageSource {\n  kind?: string\n  form?: string\n  name?: string\n  plugin?: string\n  summary?: string\n  // Entries stay nullable: any plugin may author a snapshot source, so the preview read must not trust the element shape.\n  sections?: ({ name?: string } | null)[]\n  changes?: ({ path?: string } | null)[]\n}\n\n/** Producer label for an injection event, mirroring the dsh transcript's context provenance: workspace instructions name their reconciled\n * files, a plugin source its id, any other producer its durable kind. */\nexport function injectionSourceName(source: MessageSource | null | undefined): string {\n  if (source?.kind === 'agent-instructions' && Array.isArray(source.changes)) {\n    const paths: string[] = []\n    for (const change of source.changes) {\n      const path = change?.path\n      if (typeof path === 'string' && path !== '' && !paths.includes(path)) paths.push(path)\n    }\n    if (paths.length > 0) return paths.join(', ')\n  }\n  const plugin = source?.plugin\n  if (typeof plugin === 'string' && plugin !== '') return plugin\n  const kind = source?.kind\n  return typeof kind === 'string' && kind !== '' ? kind : ''\n}\n\nexport function isInjection(source: MessageSource | null | undefined): source is MessageSource {\n  // Mirrors the dsh transcript's classification (conversation-nodes/message.ts): injected context is any durable source kind but 'user'\n  // ('user-rpc' keeps kind 'user'); the form check covers a foreign source with no kind.\n  return source !== null && source !== undefined\n    && ((typeof source.kind === 'string' && source.kind !== '' && source.kind !== 'user')\n      || typeof source.form === 'string')\n}\n"
    },
    {
      "path": "src/host/config.ts",
      "content": "/**\n * Entry configuration: the `config:` block of the `dsh-context` loader row plus the per-user display preferences. The\n * schemastery schema serves both cordis validation and the harness's Config-form generation; bound edits remount the\n * entry (the folds read them at apply), while preference edits commit volatile-only.\n */\n\nimport z from '@deepseek-ai/schemastery'\nimport type { PluginSettings } from '../shared/types'\n\nexport const DEFAULT_BOUNDS = {\n  maxRequestSteps: 1500,\n  /** Newest whole-turn window kept; trimming crosses whole turns, never mid-turn. */\n  maxKeptTurns: 300,\n  maxEvents: 400,\n  /** Pathological-session backstop only: each push ships the whole value (~150B/node). */\n  maxNodes: 2000,\n  maxArchiveNodes: 400,\n  maxFileOps: 400,\n  maxCommands: 400,\n  /** The command text caps per record; the card offers the full text through the browser's message body. */\n  maxCommandChars: 4096,\n}\n\n/** The resolved fold bounds; derived from {@link DEFAULT_BOUNDS} so the two cannot drift. */\nexport type FoldBounds = typeof DEFAULT_BOUNDS\n\nexport type Config = Partial<FoldBounds> & Partial<PluginSettings>\n\n/** Mark a field live-editable where the harness's schemastery ships `.volatile()`; a plain field where the modifier is absent, so one\n * schema serves every harness the gate admits. */\nexport function volatileField<S extends z>(field: S): S {\n  const volatile = (field as unknown as { volatile?: () => S }).volatile\n  return typeof volatile === 'function' ? volatile.call(field) : field\n}\n\nfunction count(defaultValue: number) {\n  return z.number().min(1).step(1).default(defaultValue)\n}\n\nexport const Config = z.object({\n  maxRequestSteps: count(DEFAULT_BOUNDS.maxRequestSteps),\n  maxKeptTurns: count(DEFAULT_BOUNDS.maxKeptTurns),\n  maxEvents: count(DEFAULT_BOUNDS.maxEvents),\n  maxNodes: count(DEFAULT_BOUNDS.maxNodes),\n  maxArchiveNodes: count(DEFAULT_BOUNDS.maxArchiveNodes),\n  maxFileOps: count(DEFAULT_BOUNDS.maxFileOps),\n  maxCommands: count(DEFAULT_BOUNDS.maxCommands),\n  maxCommandChars: count(DEFAULT_BOUNDS.maxCommandChars),\n  // Loose: a stale persisted value degrades to the default instead of failing the entry.\n  defaultPlacement: volatileField(z.union(['all', 'tab', 'sidebar', 'hide']).default('all').loose()),\n  defaultGranularity: volatileField(z.union(['step', 'turn']).default('step').loose()),\n  defaultTrendMode: volatileField(z.union(['total', 'delta']).default('total').loose()),\n  defaultDeltaBase: volatileField(z.union(['step', 'turn']).default('step').loose()),\n  defaultToolSort: volatileField(z.union(['size', 'count', 'name']).default('count').loose()),\n  defaultFileSort: volatileField(z.union(['count', 'lines', 'latest', 'path', 'name']).default('lines').loose()),\n  insightsEntry: volatileField(z.union(['show', 'hide']).default('show').loose()),\n  defaultDurationCurve: volatileField(z.union(['show', 'hide']).default('show').loose()),\n  overviewAutoSteps: volatileField(z.union(['100', '200', '300', 'off']).default('200').loose()),\n  defaultOverviewRange: volatileField(z.union(['today', '7d', '30d', 'all']).default('30d').loose()),\n  fleetTab: volatileField(z.union(['show', 'hide']).default('show').loose()),\n  // Loose: a stale persisted value (or a non-string) degrades to the empty default instead of failing the entry.\n  promptPrefix: volatileField(z.string().default('').loose()),\n  promptSuffix: volatileField(z.string().default('').loose()),\n})\n\nexport function resolveBounds(config: Config | undefined): FoldBounds {\n  const resolved = Config(config ?? {}) as FoldBounds & Record<string, unknown>\n  return {\n    maxRequestSteps: resolved.maxRequestSteps,\n    maxKeptTurns: resolved.maxKeptTurns,\n    maxEvents: resolved.maxEvents,\n    maxNodes: resolved.maxNodes,\n    maxArchiveNodes: resolved.maxArchiveNodes,\n    maxFileOps: resolved.maxFileOps,\n    maxCommands: resolved.maxCommands,\n    maxCommandChars: resolved.maxCommandChars,\n  }\n}\n"
    },
    {
      "path": "src/host/promptInjection.ts",
      "content": "/** System-prompt injection: two globally registered prompt sections join the configured prefix/suffix around the harness's assembled\n * prompt. Their text providers read the volatile config refs the loader updates in place, so an edit applies from the next model step\n * without remounting the entry. */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Config } from './config'\n\n/** The `ctx.systemPrompt` face consumed here; feature-detected so a composition without it degrades to a no-op. */\nexport interface SystemPromptFace {\n  section(section: {\n    name: string\n    order: number\n    text: string | ((context: unknown) => string)\n    interpolate?: boolean\n  }): () => void\n  getSectionOrder(name: string): number\n}\n\n/** The live text behind one config field: a volatile-marked field resolves to a `{ get }` reference the loader rewrites on preference\n * edits; below the volatile seam the value is the plain stored string. */\nfunction liveText(value: unknown): () => string {\n  if (value !== null && typeof value === 'object' && typeof (value as { get?: unknown }).get === 'function') {\n    const get = (value as { get: () => unknown }).get\n    return () => {\n      const text = get()\n      return typeof text === 'string' ? text : ''\n    }\n  }\n  const text = typeof value === 'string' ? value : ''\n  return () => text\n}\n\n/** The section text provider: whitespace-only text is disabled (the harness's `renderPrompt` drops empty sections), any other text stays\n * byte-exact. */\nfunction sectionText(read: () => string): (context: unknown) => string {\n  return () => {\n    const text = read()\n    return text.trim().length === 0 ? '' : text\n  }\n}\n\n/** Fixed clearance from the nearest harness-owned order anchor, outside every allocated slot. */\nconst ORDER_CLEARANCE = 1000\n\nexport function watchPromptInjection(ctx: Context, config: Config): void {\n  // Fires wherever the prompt registry exists, before or after this entry mounts; without it the entry is a no-op.\n  ctx.inject(['systemPrompt'] as never, (inner: Context) => {\n    const systemPrompt = (inner as { systemPrompt?: SystemPromptFace | null }).systemPrompt\n    if (systemPrompt === null || systemPrompt === undefined\n      || typeof systemPrompt.section !== 'function'\n      || typeof systemPrompt.getSectionOrder !== 'function') return\n    systemPrompt.section({\n      name: 'dsh-context:prompt-prefix',\n      // Ahead of every allocated slot, anchored through the harness's own order registry so a central renumbering keeps the prefix first.\n      order: systemPrompt.getSectionOrder('HARNESS_IDENTITY') - ORDER_CLEARANCE,\n      text: sectionText(liveText(config.promptPrefix)),\n      // Literal text: a user's `{{...}}` must never reach the strict variable interpolation.\n      interpolate: false,\n    })\n    systemPrompt.section({\n      name: 'dsh-context:prompt-suffix',\n      order: systemPrompt.getSectionOrder('DEPLOYMENT_PERSONA_SUFFIX') + ORDER_CLEARANCE,\n      text: sectionText(liveText(config.promptSuffix)),\n      interpolate: false,\n    })\n  })\n}\n"
    }
